item.command:
"<USER_HOME>\\.cache\\codex-runtimes\\codex-primary-runtime\\dependencies\\native\\powershell\\pwsh.exe" -NoProfile -Command "[System.IO.File]::WriteAllText('<TRIAL_A03>\\tracker.cav', @'
claim ready;
evidence tool from \"consulted tool\";
evidence correction from \"correction of a reading\";
caveat uncertain consequence material;
uncertain qualifies tool;
caveat stale consequence material;
readings checks from tool limit 16;
decisions answer limit 8 reopened by checks;
event observe value min 0 max 100;
event assess;
event correct;
event learn_stale;
on observe reveal tool;
on observe when value >= 70 sample checks = value supports ready;
on observe when value < 70 sample checks = value opposes ready;
on assess when not has_sample(checks) reject \"No reading.\";
on assess when withdrawn(latest(checks)) reject \"Reading withdrawn.\";
on assess when latest(checks) < 70 reject \"Reading too weak.\";
on assess when has_caveat(latest(checks), stale) reject \"Reading stale.\";
on assess when committed(answer) and not reopened(answer) reject \"Answer in force.\";
on assess commit answer because enough using latest(checks);
on correct when not has_sample(checks) reject \"No reading.\";
on correct when withdrawn(latest(checks)) reject \"Reading already withdrawn.\";
on correct reveal correction;
on correct withdraw latest(checks) because correction;
on correct when committed(answer) and not reopened(answer) and rests_on_withdrawn(answer)
    reopen answer because correction;
on learn_stale when not observed(tool) reject \"Tool not observed.\";
on learn_stale qualify tool with stale;
bind answer.verdict = \"none\";
bind answer.verdict = \"approved\" when committed(answer) and not reopened(answer);
bind answer.verdict = \"reopened\" when reopened(answer);

'@)
